CREATE TABLE carts (id UUID PRIMARY KEY, user_id UUID NOT NULL UNIQUE);
CREATE TABLE cart_items (id UUID PRIMARY KEY, cart_id UUID NOT NULL REFERENCES carts(id), item_id UUID NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), UNIQUE(cart_id,item_id));
CREATE TABLE orders (id UUID PRIMARY KEY, order_code TEXT NOT NULL UNIQUE, user_id UUID NOT NULL, status TEXT NOT NULL, recipient_name TEXT NOT NULL, recipient_phone TEXT NOT NULL, address_snapshot TEXT NOT NULL, delivery_date DATE NOT NULL, delivery_time_slot TEXT, card_message TEXT, notes TEXT, subtotal NUMERIC(19,2) NOT NULL CHECK(subtotal >= 0), discount_amount NUMERIC(19,2) NOT NULL CHECK(discount_amount >= 0 AND discount_amount <= subtotal), shipping_fee NUMERIC(19,2) NOT NULL CHECK(shipping_fee >= 0), total NUMERIC(19,2) NOT NULL CHECK(total = subtotal - discount_amount + shipping_fee), currency CHAR(3) NOT NULL DEFAULT 'VND', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), product_id UUID NOT NULL, sku_snapshot TEXT NOT NULL, name_snapshot TEXT NOT NULL, image_snapshot TEXT, unit_price NUMERIC(19,2) NOT NULL CHECK(unit_price >= 0), quantity INTEGER NOT NULL CHECK(quantity > 0), line_total NUMERIC(19,2) NOT NULL CHECK(line_total = unit_price * quantity));
CREATE TABLE order_status_history (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id), from_status TEXT, to_status TEXT NOT NULL, actor_id UUID, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE checkout_requests (user_id UUID NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, order_id UUID REFERENCES orders(id), PRIMARY KEY(user_id,idempotency_key));